mapper.select:
SELECT * FROM weather_forecast 
WHERE trip_id = #{tripId} AND forecast_date BETWEEN #{startDate} AND #{endDate}
ORDER BY forecast_date

mapper.update:
UPDATE weather_forecast
SET trip_id = #{tripId}, forecast_date = #{forecastDate}, city = #{city}, min_temp = #{minTemp},
    max_temp = #{maxTemp}, precipitation = #{precipitation}, humidity = #{humidity},
    uv_index = #{uvIndex}, weather_desc = #{weatherDesc}, fetch_time = #{fetchTime}
WHERE id = #{id}
